import{_ as i,l as r,o as e,c as l,v as t,p as s,x as n,d as h,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"Count-Min Sketch","description":"","frontmatter":{"title":"Count-Min Sketch","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/count-min-sketch.md","filePath":"cs/count-min-sketch.md","lastUpdated":1789023840000}'),p={name:"cs/count-min-sketch.md"};function m(u,a,_,f,A,C){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="count-min-sketch" tabindex="-1">Count-Min Sketch <a class="header-anchor" href="#count-min-sketch" aria-label="Permalink to &quot;Count-Min Sketch&quot;">​</a></h1><div class="epigraph"><p>若干行哈希表只做加法和取最小；点查询是各行估计的最小，偏高但不偏低（非负流）。</p><footer>—— 据 Cormode and Muthukrishnan, An Improved Data Stream Summary: The Count-Min Sketch and Its Applications, J. Algorithms 2005 整理</footer></div><p><a href="/cs/consistent-hashing">上一课</a> 仍精确放置键。<a href="/cs/universal-hashing">通用散列</a> 给出行间独立。<a href="/cs/bloom-filter">布隆</a> 只回答成员。流上要频次，不能存 \\(n\\) 个计数器。本课不画环。缺口是 Count-Min：宽 \\(w\\)、深 \\(d\\) 的计数矩阵。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>流中元素更新 \\((x,\\Delta)\\)，\\(\\Delta\\ge 0\\)。查询 \\(\\hat{f}(x)=\\min_j \\mathrm{CM}[j,h_j(x)]\\)。真频 \\(f(x)\\le\\hat{f}(x)\\)。取 \\(w=\\lceil e/\\varepsilon\\rceil\\)，\\(d=\\lceil\\ln(1/\\delta)\\rceil\\)，有 \\(\\Pr[\\hat{f}(x)\\gt f(x)+\\varepsilon\\|f\\|_1]\\le\\delta\\)。缺口是<strong>用最小压住其它键的碰撞噪音</strong>，空间 \\(O((1/\\varepsilon)\\log(1/\\delta))\\) 与 \\(n\\) 无关。</p><p><span class="marginnote">Cormode and Muthukrishnan, <em>Journal of Algorithms</em>, 2005。行哈希 pairwise 独立通常够用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>更新：每行 \\(h_j(x)\\) 槽加 \\(\\Delta\\)。查询取 min。合并：两个同形 sketch 对槽相加，适合分布式。负更新破坏「只偏高」，要 Count-Mean-Min 或换结构，本课钉非负。</p>',8)),(e(),s(d,null,{default:n(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%85%83%E7%B4%A0%20x%22%5D%20--%3E%20ROWS%5B%22d%20%E8%A1%8C%E7%8B%AC%E7%AB%8B%20h_j%22%5D%0A%20%20ROWS%20--%3E%20ADD%5B%22%E5%AF%B9%E5%BA%94%E6%A7%BD%20%2B%3D%20%CE%94%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20MIN%5B%22%E5%90%84%E8%A1%8C%E4%BC%B0%E8%AE%A1%E5%8F%96%20min%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 HyperLogLog：CM 估频次；HLL 估基数。与完美散列：CM 允许错，空间小。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>碰撞只把别人的质量加进来，故高估。min 降低「某一行特别倒霉」的概率。\\(\\|f\\|_1\\) 是流总质量，热键相对误差小、冷键可能被噪音淹没——这是草图边界，不是实现 bug。</p><p>不要把 CM 当神经网络压缩；是流摘要。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Count-Sketch（中位数、可负）写完。基数估计下一课 HLL。成员过滤器仍布隆/布谷。</p><p>后课默认：非负频次近似用 Count-Min。不同元素个数用 HyperLogLog。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Count-Min：高估频次，空间随 \\(\\varepsilon,\\delta\\)，与 \\(n\\) 无关。</li><li>查询取行 min；适合非负流。</li><li>下一课估基数而非频次。</li><li>出处：Cormode and Muthukrishnan, 2005。</li></ul>',9))])}const x=i(p,[["render",m]]);export{E as __pageData,x as default};
